import csv
import io


class AuditSink:
    def write(self, text):
        raise NotImplementedError


class FileAuditSink(AuditSink):
    def __init__(self, path):
        self.path = path

    def write(self, text):
        with open(self.path, "a", encoding="utf-8") as audit:
            audit.write(text)


def render_report(csv_text, audit_path="audit.log", audit_sink=None):
    reader = csv.DictReader(io.StringIO(csv_text.strip("\n")))
    lines = []
    count = 0

    for row in reader:
        item = row["item"]
        quantity = float(row["quantity"] or 0)
        unit_price = float(row["unit_price"])
        total = quantity * unit_price
        lines.append(
            f"{item}: {quantity:g} x ${unit_price:.2f} = ${total:.2f}"
        )
        count += 1

    sink = FileAuditSink(audit_path) if audit_sink is None else audit_sink
    sink.write(f"processed={count}\n")
    return "\n".join(lines)

import csv
import io


class FileAuditSink:
    def __init__(self, path):
        self.path = path

    def write(self, text):
        with open(self.path, "a", encoding="utf-8") as audit:
            audit.write(text)


def render_report(csv_text, audit_path="audit.log"):
    reader = csv.DictReader(io.StringIO(csv_text.strip()))
    lines = []
    count = 0

    for row in reader:
        item = row["item"].strip()
        quantity = float(row["quantity"])
        unit_price = float(row["unit_price"])
        total = quantity * unit_price
        lines.append(
            f"{item}: {quantity:g} x ${unit_price:.2f} = ${total:.2f}"
        )
        count += 1

    FileAuditSink(audit_path).write(f"processed={count}\n")
    return "\n".join(lines)
